// Fixture: prompt/resource-only MCP server, NO tools capability, tools/list = [].
import { createInterface } from "node:readline";
const rl=createInterface({input:process.stdin});
rl.on("line",(line)=>{let msg;try{msg=JSON.parse(line)}catch{return} const reply=(o)=>process.stdout.write(JSON.stringify(o)+"\n"); if(msg.method==="initialize"){reply({jsonrpc:"2.0",id:msg.id,result:{protocolVersion:"2024-11-05",capabilities:{prompts:{},resources:{}},serverInfo:{name:"fixture-zero-tools",version:"1.0.0"}}})}else if(msg.method==="ping"){reply({jsonrpc:"2.0",id:msg.id,result:{}})}else if(msg.method==="tools/list"){reply({jsonrpc:"2.0",id:msg.id,result:{tools:[]}})}else if(msg.method==="prompts/list"){reply({jsonrpc:"2.0",id:msg.id,result:{prompts:[{name:"greeting",description:"A greeting prompt for new users",arguments:[{name:"name",description:"Name to greet",required:false}]}]}})}else if(msg.method==="resources/list"){reply({jsonrpc:"2.0",id:msg.id,result:{resources:[{uri:"file:///example.txt",name:"example",description:"An example resource",mimeType:"text/plain"}]}})}else if(msg.method==="tools/call"){reply({jsonrpc:"2.0",id:msg.id,error:{code:-32602,message:`Unknown tool: ${msg.params?.name}`}})}else if(msg.id!==undefined){reply({jsonrpc:"2.0",id:msg.id,error:{code:-32601,message:`Method not found: ${msg.method}`}})}});
